#define NOMINMAX
#include "../src/game_module_ui.hpp"
#include "../src/ff3_play_runtime.hpp"
#include <iostream>
#include <set>
// Read-only: no controller is stepped, no inputs are installed or sent, and
// no Mags editor or HandSnapAccess writer is instantiated.
static json::Value physicsLinks(HANDLE h,addr root,ff3qb::Vec position){
 using namespace basketballUi;auto out=array();std::set<addr> visited;visited.insert(root);
 for(size_t field=0;field<0x400;field+=8){const auto target=rd<addr>(h,root+field);if(target<65536||target>0x7fffffffffffULL||target%8||!visited.insert(target).second)continue;std::array<unsigned char,0x400> memory{};SIZE_T count=0;if(!ReadProcessMemory(h,reinterpret_cast<void*>(target),memory.data(),memory.size(),&count)||count!=memory.size())continue;auto matches=array();
  for(size_t offset=0;offset+12<=memory.size();offset+=4){shooting::Vec raw{};memcpy(&raw,memory.data()+offset,sizeof raw);const auto candidate=ff3Native::vector(raw);if(ff3qb::finite(candidate)&&ff3qb::length(candidate-position)<.25)matches.a.push_back(number(offset));}
  if(!matches.a.empty()){auto row=object();row.o[L"pointerField"]=number(field);row.o[L"target"]=number(double(target));row.o[L"positionOffsets"]=matches;out.a.push_back(row);}
 }return out;
}
static std::string objectType(HANDLE h,addr object){
 const auto table=rd<addr>(h,object),locator=rd<addr>(h,table-8);if(rd<unsigned>(h,locator)!=1)return {};const auto image=locator-rd<unsigned>(h,locator+20),descriptor=image+rd<unsigned>(h,locator+12);char name[160]{};SIZE_T count=0;if(!ReadProcessMemory(h,reinterpret_cast<void*>(descriptor+16),name,sizeof name-1,&count)||count<5||name[0]!='.'||name[1]!='?')return {};return name;
}
static json::Value candidateTransforms(HANDLE h,addr part){
 using namespace basketballUi;auto out=object();const auto primitive=rd<addr>(h,part+Offsets::BasePart::Primitive),render=rd<addr>(h,part+0x180),body=rd<addr>(h,primitive+0x1e8);auto vectorAt=[&](addr field){auto raw=rd<shooting::Vec>(h,field,{NAN,NAN,NAN});auto v=array();for(double n:{double(raw.x),double(raw.y),double(raw.z)})v.a.push_back(number(n));return v;};
 out.o[L"part"]=number(double(part));out.o[L"primitive"]=number(double(primitive));out.o[L"renderCandidate"]=number(double(render));out.o[L"bodyCandidate"]=number(double(body));out.o[L"primitiveType"]=string(widen(objectType(h,primitive)));out.o[L"renderType"]=string(widen(objectType(h,render)));out.o[L"bodyType"]=string(widen(objectType(h,body)));out.o[L"position"]=vectorAt(primitive+Offsets::Primitive::Position);out.o[L"secondaryPosition"]=vectorAt(primitive+0x11c);out.o[L"renderA"]=vectorAt(render+0xac);out.o[L"renderB"]=vectorAt(render+0xdc);out.o[L"bodyA"]=vectorAt(body+0xb0);out.o[L"bodyB"]=vectorAt(body+0x140);
 for(const auto& entry:{std::pair<const wchar_t*,addr>{L"bodyRotationA",body+0x8c},{L"bodyRotationB",body+0x11c}}){auto values=array();auto matrix=rd<defense::Matrix3>(h,entry.second);for(double n:matrix.m)values.a.push_back(number(n));out.o[entry.first]=values;out.o[std::wstring(entry.first)+L"Valid"]=basketballUi::boolean(ff3Play::snapRotationValid(matrix.m));}out.o[L"bodyVelocityA"]=vectorAt(body+0xbc);out.o[L"bodyVelocityB"]=vectorAt(body+0x14c);return out;
}
int main(int argc,char** argv){
 winrt::init_apartment();HANDLE h=nullptr;DWORD pid=0;addr base=0;
 if(!connectRoblox(h,pid,base)){std::cout<<"{\"available\":false}";return 2;}
 for(int i=0;i<5;++i){gameModules::publish(inspectBasketball(h,base,pid));Sleep(200);}
 basketballConnection::entered=true;basketballConnection::releaseCurrent=true;
 if(gameModules::router.open(now(),true,true)!=gameModules::Id::FootballFusion3){CloseHandle(h);return 3;}
 ff3Play::magsOn=true;ff3Play::Reader reader;auto s=reader.read({});
 for(int i=0;i<12;++i){Sleep(40);s=reader.read({});}
 const auto hand=ff3Play::HandSnapAccess::contact(h,s);const auto balls=ff3Play::HandSnapAccess::observe(h,s,reader.looseParts);
 using namespace basketballUi;auto report=object();report.o[L"readOnly"]=basketballUi::boolean(true);report.o[L"pid"]=number(pid);report.o[L"sceneValid"]=basketballUi::boolean(s.valid);report.o[L"focused"]=basketballUi::boolean(s.focused);report.o[L"possessed"]=basketballUi::boolean(s.possessed);report.o[L"handValid"]=basketballUi::boolean(hand.valid(s));report.o[L"rightTouchEnabled"]=basketballUi::boolean(hand.touch);auto size=array();for(double v:{hand.size.x,hand.size.y,hand.size.z})size.a.push_back(number(v));report.o[L"rightSize"]=size;report.o[L"looseBalls"]=number(double(balls.size()));auto nearby=array();
 auto vec=[](ff3qb::Vec value){auto out=array();for(double v:{value.x,value.y,value.z})out.a.push_back(number(v));return out;};
 report.o[L"handPosition"]=vec(hand.position);report.o[L"headPosition"]=vec(s.head);
 {auto zones=array();const auto contacts=ff3Native::catchParts(h,s.own);for(auto part:{contacts.first,contacts.second}){if(!part)continue;auto zone=object();const auto primitive=rd<addr>(h,part+Offsets::BasePart::Primitive);zone.o[L"part"]=number(double(part));zone.o[L"primitive"]=number(double(primitive));zone.o[L"name"]=string(widen(nm(h,part)));zone.o[L"parent"]=number(double(rd<addr>(h,part+Offsets::Instance::Parent)));zone.o[L"size"]=vec(ff3Native::partSize(h,part));zone.o[L"position"]=vec(ff3Native::position(h,part));zone.o[L"flags"]=number(rd<unsigned char>(h,primitive+Offsets::Primitive::Flags,255));auto rotation=array();for(double n:rd<defense::Matrix3>(h,primitive+Offsets::Primitive::Rotation).m)rotation.a.push_back(number(n));zone.o[L"rotation"]=rotation;zones.a.push_back(zone);}report.o[L"catchZones"]=zones;report.o[L"character"]=number(double(s.own));}
 {auto actual=child(h,s.own,"RightHand");bool r6=false;if(!actual){actual=child(h,s.own,"Right Arm");r6=true;}const auto primitive=rd<addr>(h,actual+Offsets::BasePart::Primitive);const auto size=ff3Native::partSize(h,actual),position=ff3Native::position(h,actual);const auto rotation=rd<defense::Matrix3>(h,primitive+Offsets::Primitive::Rotation);const double offset=r6?-size.y*.5+.15:0;const auto palm=position+ff3qb::Vec{rotation.m[1],rotation.m[4],rotation.m[7]}*offset;report.o[L"actualHandPart"]=number(double(actual));report.o[L"actualHandName"]=string(widen(nm(h,actual)));report.o[L"actualHandSize"]=vec(size);report.o[L"actualPalmPosition"]=vec(palm);report.o[L"catchToPalmDistance"]=number(ff3Play::snapDistance(hand.position,palm));}
 const bool links=argc>1&&std::string(argv[1])=="--physics-links";const bool audit=links||argc>1&&std::string(argv[1])=="--motion-audit";
 for(const auto& b:balls){auto item=object();const auto& p=b.part.part;item.o[L"id"]=number(double(p.id));item.o[L"distanceToHand"]=number(ff3qb::length(b.part.position-hand.position));item.o[L"anchored"]=basketballUi::boolean(b.anchored);item.o[L"eligibleAt20"]=basketballUi::boolean(hand.valid(s)&&ff3Play::HandSnap::eligible(s,b,hand,20));
  if(audit){item.o[L"name"]=string(widen(nm(h,p.id)));item.o[L"parentName"]=string(widen(nm(h,p.rig)));item.o[L"parentClass"]=string(widen(defense::classOf(h,p.rig)));item.o[L"primitive"]=number(double(p.primitive));item.o[L"flags"]=number(rd<unsigned char>(h,p.primitive+Offsets::Primitive::Flags,255));item.o[L"position"]=vec(b.part.position);item.o[L"velocity"]=vec(b.velocity);item.o[L"size"]=vec(p.size);item.o[L"meshOffset"]=vec(ff3Native::vector(rd<shooting::Vec>(h,p.mesh+Offsets::DataModelMesh::Offset,{NAN,NAN,NAN})));item.o[L"meshScale"]=vec(b.part.meshScale);auto contents=array();
   for(auto node:children(h,p.id)){auto row=object();const auto kind=defense::classOf(h,node);row.o[L"class"]=string(widen(kind));row.o[L"name"]=string(widen(nm(h,node)));if(defense::partClass(kind))row.o[L"position"]=vec(ff3Native::position(h,node));contents.a.push_back(row);}item.o[L"children"]=contents;
  }nearby.a.push_back(item);}report.o[L"balls"]=nearby;
 if(links){auto roots=array();size_t total=0;for(const auto& b:balls){if(total++>=8)break;const auto& p=b.part.part;auto row=object();row.o[L"ball"]=number(double(p.id));row.o[L"position"]=vec(b.part.position);row.o[L"primitiveLinks"]=physicsLinks(h,p.primitive,b.part.position);row.o[L"instanceLinks"]=physicsLinks(h,p.id,b.part.position);row.o[L"ownerField"]=number(double(rd<addr>(h,p.primitive+Offsets::Primitive::Owner)));row.o[L"transforms"]=candidateTransforms(h,p.id);roots.a.push_back(row);}report.o[L"physicsLinks"]=roots;report.o[L"rightCatchTransforms"]=candidateTransforms(h,hand.id);report.o[L"rootTransforms"]=candidateTransforms(h,child(h,s.own,"HumanoidRootPart"));}
 if(links){auto raw=array();for(auto part:children(h,reader.workspace)){if(nm(h,part)!="Football"||!instanceClassIs(h,part,"Part")&&!instanceClassIs(h,part,"MeshPart"))continue;auto row=object();const auto primitive=rd<addr>(h,part+Offsets::BasePart::Primitive);row.o[L"part"]=number(double(part));row.o[L"rawDistance"]=number(ff3Play::snapDistance(ff3Native::position(h,part),hand.position));ff3Play::SnapWorldPoses poses{};row.o[L"posePairValid"]=basketballUi::boolean(ff3Play::readSnapWorldPoses(h,primitive,poses));row.o[L"gravityMetadata"]=basketballUi::boolean(path(h,part,{"Configuration","Gravity"})!=0);const auto by=child(h,part,"ThrownBy"),thrower=by?rd<addr>(h,by+Offsets::Misc::Value):0;row.o[L"ownThrow"]=basketballUi::boolean(thrower&&(thrower==s.player||thrower==s.own));row.o[L"transforms"]=candidateTransforms(h,part);raw.a.push_back(row);}report.o[L"unfilteredRootBalls"]=raw;}
 std::cout<<winrt::to_string(json::dump(report));CloseHandle(h);winrt::uninit_apartment();
}
